using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Colors;
using Autodesk.AutoCAD.Runtime;
using MedGas2024.Core;
using MedGas2024.Engine;
[assembly:CommandClass(typeof(LabelRuntimeTests))]
public static class LabelRuntimeTests
{
    static List<string> log=new List<string>();static void Check(bool value,string text){if(!value)throw new System.Exception(text);log.Add("PASS: "+text);}
    static bool Reject(Action action){try{action();return false;}catch(InvalidOperationException){return true;}}
    static ObjectId Layer(Database db,string name,ObjectId type,bool locked=false){using(var tr=db.TransactionManager.StartTransaction()){var table=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForWrite);var layer=new LayerTableRecord{Name=name,LinetypeObjectId=type,Color=Color.FromColorIndex(ColorMethod.ByAci,3),IsLocked=locked};table.Add(layer);tr.AddNewlyCreatedDBObject(layer,true);tr.Commit();return layer.ObjectId;}}
    static ObjectId Type(Database db,ObjectId style,string name,string text){using(var tr=db.TransactionManager.StartTransaction()){var table=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForWrite);var t=new LinetypeTableRecord{Name=name,Comments="original "+text,NumDashes=3,PatternLength=70};table.Add(t);tr.AddNewlyCreatedDBObject(t,true);t.SetDashLengthAt(0,40);t.SetDashLengthAt(1,-15);t.SetDashLengthAt(2,-15);t.SetShapeStyleAt(1,style);t.SetShapeScaleAt(1,2.5);t.SetTextAt(1,text);t.SetShapeOffsetAt(1,new Vector2d(-6,-1));tr.Commit();return t.ObjectId;}}
    static ObjectId Pipe(Database db,ObjectId layer,ObjectId type,double scale,bool line=false,ObjectId owner=default(ObjectId))
    {
        using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var space=(BlockTableRecord)tr.GetObject(owner.IsNull?bt[BlockTableRecord.ModelSpace]:owner,OpenMode.ForWrite);Entity e;if(line)e=new Line(Point3d.Origin,new Point3d(300,0,0));else{var p=new Polyline();p.AddVertexAt(0,new Point2d(0,0),0,2,3);p.AddVertexAt(1,new Point2d(300,0),0,3,4);p.AddVertexAt(2,new Point2d(300,300),0,4,4);p.Plinegen=true;e=p;}space.AppendEntity(e);tr.AddNewlyCreatedDBObject(e,true);e.LayerId=layer;e.LinetypeId=type;e.LinetypeScale=scale;e.Color=Color.FromRgb(10,20,30);tr.Commit();return e.ObjectId;}
    }
    static string Geometry(Database db,ObjectId id){using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var e=(Entity)tr.GetObject(id,OpenMode.ForRead);var p=e as Polyline;return e.LayerId.Handle+"|"+(p==null?((Line)e).StartPoint+"|"+((Line)e).EndPoint:String.Join(";",Enumerable.Range(0,p.NumberOfVertices).Select(i=>p.GetPoint3dAt(i)+":"+p.GetBulgeAt(i)))+"|"+ScaleService.WidthState(p,tr));}}
    static ObjectId[] Texts(Database db){using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);return ((BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead)).Cast<ObjectId>().Where(id=>tr.GetObject(id,OpenMode.ForRead) is MText).ToArray();}}
    static int TypeCount(Database db){using(var tr=db.TransactionManager.StartOpenCloseTransaction())return ((LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead)).Cast<ObjectId>().Count();}
    [CommandMethod("MRTLABELTEST",CommandFlags.Modal)]public static void Run()
    {
        log.Clear();var previous=HostApplicationServices.WorkingDatabase;string root=Directory.GetParent(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)).FullName;
        try
        {
            using(var db=new Database(true,true))
            {
                HostApplicationServices.WorkingDatabase=db;ObjectId style;using(var tr=db.TransactionManager.StartTransaction()){var styles=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForWrite);var st=new TextStyleTableRecord{Name="LABEL_TEST_STYLE",FileName="arial.ttf",TextSize=0,XScale=1};styles.Add(st);tr.AddNewlyCreatedDBObject(st,true);style=st.ObjectId;tr.Commit();}
                string lin=Path.Combine(root,"evidence","label-test-input.lin");File.WriteAllText(lin,"*LABEL_RAW_U,Native upright source\nA,40,-15,[\"D15.Oxy\",LABEL_TEST_STYLE,S=2.5,U=0,X=-6,Y=-1],-15\n",System.Text.Encoding.ASCII);db.LoadLineTypeFile("LABEL_RAW_U",lin);ObjectId oxy;using(var tr=db.TransactionManager.StartOpenCloseTransaction())oxy=((LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead))["LABEL_RAW_U"];
                ObjectId alias=Type(db,style,"ALIAS_15","Oxy.D15"),oxy22=Type(db,style,"OXY_22","D22.Oxy"),co2=Type(db,style,"CO2_15","D15.CO2");ObjectId a=Layer(db,"Mr.T_OXY_D15_RAW",oxy),b=Layer(db,"CUSTOM_B",co2),c=Layer(db,"Mr.T_OXY_D22_RAW",oxy22),locked=Layer(db,"LOCKED",oxy,true);
                ObjectId p1=Pipe(db,a,db.ByLayerLinetype,.1),p2=Pipe(db,b,oxy,.2,true),other=Pipe(db,a,co2,.3),p4=Pipe(db,c,db.ByLayerLinetype,.5),p5=Pipe(db,a,alias,.7),p6=Pipe(db,locked,db.ByLayerLinetype,.8),plain=Pipe(db,b,db.ContinuousLinetype,1);
                ObjectId block;using(var tr=db.TransactionManager.StartTransaction()){var table=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForWrite);var nested=new BlockTableRecord{Name="NESTED_LABEL"};table.Add(nested);tr.AddNewlyCreatedDBObject(nested,true);block=nested.ObjectId;tr.Commit();}ObjectId nestedId=Pipe(db,a,oxy,.9,false,block);
                var catalog=LabelService.Read(db);Check(catalog.Members.Count==6&&catalog.NoLabel==1,"Native scan counts direct labeled curves and excludes nested/block and plain geometry");var key=LabelRules.Key("D15.Oxy",false);var group=catalog.Groups(false).Single(g=>g.Key==key);Check(group.Lines==4&&group.Layers==3&&group.Types==2&&group.Locked==1,"One native label group spans layer inheritance, explicit overrides and type aliases");
                Check(LabelService.KeyFromPipe(db,p2,false)==key,"Picking an explicitly typed pipe finds its actual label rather than its layer's CO2 label");string geo=Geometry(db,p1),otherGeo=Geometry(db,other),nestedGeo=Geometry(db,nestedId);var edit=new LabelEdit{ForceR=true,ChangeColor=true,Aci=201,ChangeScale=true,Scale=.25};var scope=new LabelScope{Keys=new[]{key},Fingerprint=catalog.Fingerprint};int typesBefore=TypeCount(db);
                var plan=LabelService.Inspect(db,scope,edit);Check(plan.Matched==4&&plan.Items.Count==3&&plan.Skipped.Count==1&&TypeCount(db)==typesBefore,"Read-only preview expands the whole group and reports the locked member");LabelService.Apply(db,plan,edit);
                using(var tr=db.TransactionManager.StartOpenCloseTransaction())
                {
                    var first=(Entity)tr.GetObject(p1,OpenMode.ForRead);var second=(Entity)tr.GetObject(p2,OpenMode.ForRead);var legacy=(Entity)tr.GetObject(p5,OpenMode.ForRead);Check(first.LinetypeScale==.25&&second.LinetypeScale==.25&&legacy.LinetypeScale==.25&&first.Color.ColorIndex==201&&second.Color.ColorIndex==201&&legacy.Color.ColorIndex==201,"Every eligible group member receives R0/color/scale including previous entity overrides");Check(first.LinetypeId==db.ByLayerLinetype&&second.LinetypeId==oxy&&legacy.LinetypeId==alias,"R0 preserves Linetype identity and returns matching pipes to ByLayer; foreign-layer overrides keep their proper system type");var result=(LinetypeTableRecord)tr.GetObject(oxy,OpenMode.ForRead);Check(result.TextAt(1)=="D15.Oxy"&&result.ShapeStyleAt(1)==style&&result.ShapeScaleAt(1)==2.5&&result.ShapeRotationAt(1)==0&&!result.ShapeIsUcsOrientedAt(1),"Converted native record retains the real label/font/height and uses relative rotation zero");Check(((LayerTableRecord)tr.GetObject(a,OpenMode.ForRead)).LinetypeObjectId==oxy&&((LinetypeTableRecord)tr.GetObject(oxy,OpenMode.ForRead)).TextAt(1)=="D15.Oxy","Layer and original Linetype identity are preserved while its definition is updated to R0");Check(result.Name=="LABEL_RAW_U"&&TypeCount(db)==typesBefore,"R0 does not create hashed names or extra Linetype records");Check(((Entity)tr.GetObject(other,OpenMode.ForRead)).LinetypeId==co2&&((Entity)tr.GetObject(other,OpenMode.ForRead)).Color.Red==10&&((Entity)tr.GetObject(other,OpenMode.ForRead)).LinetypeScale==.3,"Different label on the same layer is untouched");Check(((Entity)tr.GetObject(p6,OpenMode.ForRead)).LinetypeScale==.8&&((Polyline)tr.GetObject(p6,OpenMode.ForRead)).Plinegen,"Locked group member remains unchanged");Check(!((Polyline)first).Plinegen,"Processed polyline generation is Disabled");
                }
                Check(Geometry(db,p1)==geo&&Geometry(db,other)==otherGeo&&Geometry(db,nestedId)==nestedGeo&&Texts(db).Length==0,"Geometry/width are preserved and conversion creates no MText");Check(!db.Plinegen,"Successful group edit sets the new-polyline default PLINEGEN=0");
                catalog=LabelService.Read(db);int stableTypes=TypeCount(db);var repeat=LabelService.Inspect(db,new LabelScope{Keys=new[]{key},Fingerprint=catalog.Fingerprint},new LabelEdit{ForceR=true});Check(repeat.Types.All(t=>!t.Create),"Already generated unchanged R0 records are reused");LabelService.Apply(db,repeat,new LabelEdit{ForceR=true});Check(TypeCount(db)==stableTypes,"Repeated R0 conversion does not accumulate definitions");
                catalog=LabelService.Read(db);var multiply=new LabelEdit{ChangeScale=true,Multiply=true,Scale=.5};var systemScope=new LabelScope{SystemMode=true,Keys=new[]{LabelRules.Key("Oxy",true)},Fingerprint=catalog.Fingerprint};var multiplyPlan=LabelService.Inspect(db,systemScope,multiply);Check(multiplyPlan.Matched==5&&multiplyPlan.Items.Count==4,"System scope includes both Oxy diameters and still reports locked curves");LabelService.Apply(db,multiplyPlan,multiply);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){Check(((Entity)tr.GetObject(p1,OpenMode.ForRead)).LinetypeScale==.125&&((Entity)tr.GetObject(p4,OpenMode.ForRead)).LinetypeScale==.25,"Multiplication preserves the ratio between different original scales");}
                catalog=LabelService.Read(db);var widthEdit=new LabelEdit{ChangeWidth=true,Width=12};var widthPlan=LabelService.Inspect(db,new LabelScope{Keys=new[]{key},Fingerprint=catalog.Fingerprint},widthEdit);Check(widthPlan.Items.Count==2&&widthPlan.Skipped.Count==2,"Width-only changes skip LINE and locked polyline");LabelService.Apply(db,widthPlan,widthEdit);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var p=(Polyline)tr.GetObject(p1,OpenMode.ForRead);Check(p.ConstantWidth==12&&p.LinetypeScale==.125&&p.GetPoint2dAt(1)==new Point2d(300,0),"Width action retains scale and vertex coordinates");}
                var linkedOptions=new DirectionOptions();DirectionService.Apply(db,DirectionService.Inspect(db,new[]{other},linkedOptions),linkedOptions);var linkedTexts=Texts(db);Check(linkedTexts.Length>0,"Fixture contains old linked MText route labels");catalog=LabelService.Read(db);var coScope=new LabelScope{Keys=new[]{LabelRules.Key("D15.CO2",false)},Fingerprint=catalog.Fingerprint};Check(LabelService.Inspect(db,coScope,new LabelEdit{ChangeColor=true,Aci=1}).Items.Count==0,"Old linked labels require native conversion before color-only edits");var restorePlan=LabelService.Inspect(db,coScope,new LabelEdit{ForceR=true});stableTypes=TypeCount(db);Check(Reject(()=>LabelService.Apply(db,restorePlan,new LabelEdit{ForceR=true},true))&&linkedTexts.All(id=>!id.IsErased)&&TypeCount(db)==stableTypes,"Injected failure rolls back native definitions and linked-label removal together");LabelService.Apply(db,restorePlan,new LabelEdit{ForceR=true});Check(linkedTexts.All(id=>id.IsErased)&&Texts(db).Length==0,"Native conversion removes only the tool's owned linked MText labels");
                catalog=LabelService.Read(db);var allScope=new LabelScope{All=true,Fingerprint=catalog.Fingerprint};var colorEdit=new LabelEdit{ChangeColor=true,Aci=30};var stale=LabelService.Inspect(db,allScope,colorEdit);using(var tr=db.TransactionManager.StartTransaction()){((Entity)tr.GetObject(p1,OpenMode.ForWrite)).LinetypeScale=.4;tr.Commit();}Check(Reject(()=>LabelService.Apply(db,stale,colorEdit)),"A reviewed plan cannot overwrite a newer entity state");catalog=LabelService.Read(db);Check(LabelService.Inspect(db,new LabelScope{All=true,Fingerprint=catalog.Fingerprint},colorEdit).Matched==6,"All-label scope includes every labeled curve regardless of group filters");
                var dxfPath=Path.Combine(root,"evidence","r0-preserved-name.dxf");db.DxfOut(dxfPath,16,DwgVersion.AC1032);var dxfLines=File.ReadAllLines(dxfPath);var textFlags=new List<int>();bool inType=false;string recordName="";for(int di=0;di+1<dxfLines.Length;di+=2){string code=dxfLines[di].Trim(),value=dxfLines[di+1].Trim();if(code=="0"){inType=value=="LTYPE";recordName="";}else if(inType&&code=="2")recordName=value;else if(inType&&recordName=="LABEL_RAW_U"&&code=="74")textFlags.Add(Int32.Parse(value));}Check(textFlags.Contains(2)&&textFlags.All(f=>f==0||f==2),"DXF reports relative text element flags exactly 2 under the preserved name, with no extra orientation flags");
                db.SaveAs(Path.Combine(root,"evidence","label-regression.dwg"),DwgVersion.AC1032);
            }log.Add("RESULT: PASS; scratch database only. Rendering/REVERSE/Undo/Plot still require visual CAD checks.");
        }catch(System.Exception ex){log.Add("RESULT: FAIL");log.Add(ex.ToString());}finally{HostApplicationServices.WorkingDatabase=previous;File.WriteAllLines(Path.Combine(root,"evidence","label-runtime-tests.txt"),log);var doc=Autodesk.AutoCAD.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument;if(doc!=null)doc.Editor.WriteMessage("\n"+String.Join("\n",log)+"\n");}
    }
}
